contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint a, uint b) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a) + (b)); require(a <= 1000000000000000000000000000000); require(b <= 1000000000000000000000000000000);
        require(a > 0 && b > 0);
        require(address(this).balance >= a + b);
        c.addToBalance{value: a}(); if (__ESBMC_reverted()) return;
        c.addToBalance{value: b}(); if (__ESBMC_reverted()) return;
        uint pre = address(c).balance;
        uint recorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint balAfter = address(c).balance;
        uint recAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        assert(
            (reverted && balAfter == pre && recAfter == recorded && recorded == a + b) ||
            (!reverted && balAfter + recorded == pre && recAfter == 0)
        );
    }
}

