// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 a, uint256 b) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        b = bound(b, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a > 0 && b > 0);
        vm.assume(address(this).balance >= a + b);
        try c.addToBalance{value: a}() {} catch { return; }
        try c.addToBalance{value: b}() {} catch { return; }
        uint pre = address(c).balance;
        uint256 recorded;
        try c.getBalance(address(this)) returns (uint256 __r) { recorded = __r; } catch { return; }
        bool reverted;
        try c.withdrawBalance() { reverted = false; } catch { reverted = true; }
        uint balAfter = address(c).balance;
        uint256 recAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { recAfter = __r; } catch { return; }
        assertTrue((reverted && balAfter == pre && recAfter == recorded && recorded == a + b) ||
            (!reverted && balAfter + recorded == pre && recAfter == 0));
    }

    function testFuzz_run(uint256 a, uint256 b) public {
        _run(a, b);
    }

    receive() external payable {}
}
